arguments.prompt:
You are working in /tmp/sv-75f9323fc5c64f03b265d4affe67cb33/ShipmentTracker. This is a Blazor Web App with Interactive Auto Global mode and Individual authentication. The solution has two projects:
- ShipmentTracker (server) 
- ShipmentTracker.Client (WebAssembly client)

The app is for a logistics company that tracks shipments. Implement the following:

## Requirements
1. Dispatchers view a list of shipments with status and destination
2. Customers check their shipment status and estimated delivery
3. Every page has interactive controls
4. Staff (dispatchers) and customers authenticate with individual accounts

## What to do

### 1. Remove template demo pages
Delete these files from ShipmentTracker.Client/Pages/:
- Counter.razor
- Weather.razor

### 2. Create shared models in ShipmentTracker.Client (since interactive components must live there)

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}
```

### 3. Create the service interface in the Client project

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<List<Shipment>> GetShipmentsForCustomerAsync(string email);
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<Shipment?> UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}
```

### 4. Create client-side implementation using HttpClient

Create `ShipmentTracker.Client/Services/ShipmentHttpService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentHttpService : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentHttpService(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
    {
        return await _http.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(email)}") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        try
        {
            return await _http.GetFromJsonAsync<Shipment>($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
        }
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }
    }

    public async Task<Shipment?> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var response = await _http.PutAsJsonAsync($"api/shipments/{id}/status", status);
        if (response.IsSuccessStatusCode)
            return await response.Content.ReadFromJsonAsync<Shipment>();
        return null;
    }
}
```

### 5. Register HttpClient and service in Client Program.cs

Edit `ShipmentTracker.Client/Program.cs` to add:
```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddHttpClient("ShipmentTracker.ServerAPI", client =>
    client.BaseAddress = new Uri(builder.HostEnvironment.BaseAddress));
builder.Services.AddScoped(sp => sp.GetRequiredService<IHttpClientFactory>().CreateClient("ShipmentTracker.ServerAPI"));
builder.Services.AddScoped<IShipmentService, ShipmentHttpService>();

await builder.Build().RunAsync();
```

### 6. Create server-side service implementation

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
namespace ShipmentTracker.Services;

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

public class ShipmentServerService : IShipmentService
{
    // In-memory seed data for demo purposes
    private static readonly List<Shipment> _shipments = new()
    {
        new Shipment { Id = 1, TrackingNumber = "TRK-001234", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, CreatedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes" },
        new Shipment { Id = 2, TrackingNumber = "TRK-001235", Origin = "Chicago, IL", Destination = "Miami, FL", Status = ShipmentStatus.Pending, CreatedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(5), CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet" },
        new Shipment { Id = 3, TrackingNumber = "TRK-001236", Origin = "Seattle, WA", Destination = "Denver, CO", Status = ShipmentStatus.OutForDelivery, CreatedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "alice@example.com", Description = "Medical supplies" },
        new Shipment { Id = 4, TrackingNumber = "TRK-001237", Origin = "Boston, MA", Destination = "Houston, TX", Status = ShipmentStatus.Delivered, CreatedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(-1), CustomerEmail = "carol@example.com", Description = "Auto parts - 3 boxes" },
        new Shipment { Id = 5, TrackingNumber = "TRK-001238", Origin = "San Francisco, CA", Destination = "Phoenix, AZ", Status = ShipmentStatus.Delayed, CreatedDate = DateTime.UtcNow.AddDays(-4), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "bob@example.com", Description = "Perishable goods - refrigerated" },
    };

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
    {
        var results = _shipments.Where(s => s.CustomerEmail.Equals(email, StringComparison.OrdinalIgnoreCase)).ToList();
        return Task.FromResult(results);
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<Shipment?> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment != null)
        {
            shipment.Status = status;
        }
        return Task.FromResult(shipment);
    }
}
```

### 7. Add API endpoints and register server service in server Program.cs

Edit `ShipmentTracker/Program.cs`. After the existing service registrations (after `builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();`) add:
```csharp
builder.Services.AddScoped<IShipmentService, ShipmentServerService>();
```

You'll need these usings at the top:
```csharp
using ShipmentTracker.Client.Services;
using ShipmentTracker.Services;
```

Before `app.Run();` add the API endpoints:
```csharp
// Shipment API endpoints
var shipmentApi = app.MapGroup("/api/shipments").RequireAuthorization();

shipmentApi.MapGet("/", async (IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()));

shipmentApi.MapGet("/customer/{email}", async (string email, IShipmentService service) =>
    Results.Ok(await service.GetShipmentsForCustomerAsync(email)));

shipmentApi.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});

shipmentApi.MapPut("/{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
{
    var shipment = await service.UpdateShipmentStatusAsync(id, status);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});
```

You'll need `using ShipmentTracker.Client.Models;` for the ShipmentStatus in the endpoint.

### 8. Create the pages in ShipmentTracker.Client/Pages/

**Home.razor** - Replace the existing one:
```razor
@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Shipment Tracker</h1>
<p class="lead">Welcome to the logistics shipment tracking system.</p>

<AuthorizeView>
    <Authorized>
        <div class="row mt-4">
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">📦 Track a Shipment</h5>
                        <p class="card-text">Enter your tracking number to check shipment status and estimated delivery.</p>
                        <a href="/track" class="btn btn-primary">Track Now</a>
                    </div>
                </div>
            </div>
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">📋 My Shipments</h5>
                        <p class="card-text">View all shipments associated with your account.</p>
                        <a href="/my-shipments" class="btn btn-primary">View Shipments</a>
                    </div>
                </div>
            </div>
        </div>
    </Authorized>
